class SHelper {
	private $file;
	private $buffer = [];
	private $pos = 0;

	public function Init() {
		$this->file = fopen("php://stdin", "r");
		$this->buffer = [];
		$this->pos = 0;
	}

	private function ReadToken() {
		while ($this->pos >= count($this->buffer)) {
			$line = fgets($this->file);
			if ($line === false) {
				return false;
			}
			$this->buffer = preg_split('/\s+/', trim($line), -1, PREG_SPLIT_NO_EMPTY);
			$this->pos = 0;
		}
		return $this->buffer[$this->pos++];
	}

	public function ReadInt64() {
		$token = $this->ReadToken();
		if ($token === false || !preg_match('/^[+-]?\d+$/', $token)) {
			throw new Exception("parse error");
		}
		return intval($token);
	}
}

main();
